import { MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, color, float } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ShapeGeometry, BoxGeometry, Vector3 } = ctx.THREE;

  const root = new Group();
  root.name = 'TestimonialPanel';

  // ---------- Config & Helpers ----------
  const width = 3.4;
  const height = 1.9;
  const radius = 0.06;
  const padding = 0.5; // 2 × base unit
  const colors = config.colors ?? config.visualSpec?.colors ?? {};

  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#1a1a22' },
    { at: 1, hex: '#111116' }
  ];
  const gradTop = gradientStops[0].hex;
  const gradBottom = gradientStops[gradientStops.length - 1].hex;

  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#16161d';

  // ---------- Panel Geometry ----------
  const shape = new Shape();
  shape.moveTo(-width / 2 + radius, -height / 2);
  shape.lineTo(width / 2 - radius, -height / 2);
  shape.quadraticCurveTo(width / 2, -height / 2, width / 2, -height / 2 + radius);
  shape.lineTo(width / 2, height / 2 - radius);
  shape.quadraticCurveTo(width / 2, height / 2, width / 2 - radius, height / 2);
  shape.lineTo(-width / 2 + radius, height / 2);
  shape.quadraticCurveTo(-width / 2, height / 2, -width / 2, height / 2 - radius);
  shape.lineTo(-width / 2, -height / 2 + radius);
  shape.quadraticCurveTo(-width / 2, -height / 2, -width / 2 + radius, -height / 2);
  shape.closePath();

  const panelGeo = new ShapeGeometry(shape);
  const panelMat = new MeshStandardNodeMaterial({
    color: mix(color(gradTop), color(gradBottom), uv().y),
    roughness: float(0.6),
    metalness: float(0.2),
    clearcoat: float(0.1),
    transparent: true,
    opacity: 0 // start invisible for fade‑up
  });
  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.name = 'Panel';
  root.add(panelMesh);

  // ---------- Text Items ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // We'll keep references for cleanup
  const disposables = { materials: [panelMat], geometries: [panelGeo] };
  const timelines = [];

  // Helper to create text via atlas
  function createAtlasText(content, opts) {
    const txtObj = ctx.fontAtlas.createText(content, opts);
    // Ensure it receives a transparent material when needed
    if (txtObj.traverse) {
      txtObj.traverse((child) => {
        if (child.isMesh && child.material) {
          child.material.transparent = true;
          disposables.materials.push(child.material);
        }
        if (child.isMesh && child.geometry) {
          disposables.geometries.push(child.geometry);
        }
      });
    }
    return txtObj;
  }

  // Positioning helpers
  const topLeftX = -width / 2 + padding;
  const topLeftY = height / 2 - padding;

  // We'll manually place each role according to spec
  // 1. Quote Mark (oversized)
  const quoteMarkItem = items.find((it) => it.role === 'quote-mark');
  if (quoteMarkItem) {
    const qm = createAtlasText(quoteMarkItem.text, {
      fontSize: quoteMarkItem.typography?.fontSize ?? 62,
      color: accentHex,
      align: 'left'
    });
    qm.position.set(topLeftX, topLeftY, 0.02);
    qm.name = 'QuoteMark';
    root.add(qm);
  }

  // Baseline offsets after quote mark
  const baselineStep = 0.25; // spec step
  const quoteY = topLeftY - baselineStep - baselineStep; // 0.25 below mark + 0.25 grid
  const attributionY = quoteY - baselineStep;
  const captionY = attributionY - baselineStep;

  // 2. Quote Text
  const quoteItem = items.find((it) => it.role === 'quote');
  if (quoteItem) {
    const txt = createAtlasText(quoteItem.text, {
      fontSize: quoteItem.typography?.fontSize ?? 20,
      color: colors.ink ?? '#16161d',
      align: 'left'
    });
    txt.position.set(topLeftX, quoteY, 0.03);
    txt.name = 'Quote';
    root.add(txt);
  }

  // 3. Attribution Row with accent rule
  const attrItem = items.find((it) => it.role === 'attribution');
  if (attrItem) {
    // Accent rule (thin rectangle)
    const ruleW = 0.2;
    const ruleH = 0.02;
    const ruleGeo = new BoxGeometry(ruleW, ruleH, 0.001);
    const ruleMat = new MeshStandardNodeMaterial({
      color: color(accentHex),
      emissive: color(accentHex),
      emissiveIntensity: float(1.4)
    });
    disposables.geometries.push(ruleGeo);
    disposables.materials.push(ruleMat);
    const ruleMesh = new Mesh(ruleGeo, ruleMat);
    ruleMesh.position.set(
      topLeftX - ruleW / 2 - 0.05,
      attributionY,
      0.02
    );
    ruleMesh.name = 'AccentRule';
    root.add(ruleMesh);

    // Attribution text
    const txt = createAtlasText(attrItem.text, {
      fontSize: attrItem.typography?.fontSize ?? 13,
      color: colors.paper ?? '#e8ecf2',
      align: 'left'
    });
    txt.position.set(topLeftX + ruleW + 0.02, attributionY, 0.03);
    txt.name = 'Attribution';
    root.add(txt);
  }

  // 4. Caption
  const captionItem = items.find((it) => it.role === 'caption');
  if (captionItem) {
    const txt = createAtlasText(captionItem.text, {
      fontSize: captionItem.typography?.fontSize ?? 9,
      color: colors.paper ?? '#e8ecf2',
      align: 'left'
    });
    txt.position.set(topLeftX, captionY, 0.03);
    txt.name = 'Caption';
    root.add(txt);
  }

  // ---------- Animations ----------
  // Fade‑up panel
  const panelTimeline = gsap.timeline({
    defaults: {
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }
  });
  panelTimeline.fromTo(
    panelMesh.material,
    { opacity: 0 },
    { opacity: 1 },
    0
  );
  panelTimeline.fromTo(
    panelMesh.position,
    { y: 0.2 },
    { y: 0 },
    0
  );

  // Quote‑mark settle scale
  const qmGroup = root.getObjectByName('QuoteMark');
  if (qmGroup) {
    const settleTl = gsap.timeline();
    settleTl.fromTo(
      qmGroup.scale,
      { x: 1.04, y: 1.04, z: 1.04 },
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' },
      0
    );
    timelines.push(settleTl);
  }

  timelines.push(panelTimeline);

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill && t.kill());
    disposables.materials.forEach((m) => m.dispose && m.dispose());
    disposables.geometries.forEach((g) => g.dispose && g.dispose());
    // Dispose any added meshes if they hold extra resources
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
        if (obj.material && obj.material.dispose) obj.material.dispose();
      }
    });
  };

  return root;
}
